def restore_snapshots() -> None:
    """Restore the old REST-shaped storage before dropping normalized observations."""
    connection = op.get_bind()
    metadata = sa.MetaData()
    metadata.reflect(
        connection,
        only=[
            "game_details",
            "profile_trophies",
            "trophies",
            "detail_trophy_groups",
            "trophy_groups",
        ],
    )
    details = metadata.tables["game_details"]
    progress = metadata.tables["profile_trophies"]
    trophies = metadata.tables["trophies"]
    links = metadata.tables["detail_trophy_groups"]
    groups = metadata.tables["trophy_groups"]
    for row in connection.execute(sa.select(details)).mappings().all():
        rows = (
            connection.execute(
                sa.select(trophies, progress.c.earned, progress.c.earned_at, progress.c.earned_rate)
                .join(
                    progress,
                    (trophies.c.service == progress.c.service)
                    & (trophies.c.set_id == progress.c.set_id)
                    & (trophies.c.trophy_id == progress.c.trophy_id),
                )
                .where(progress.c.uid == row["uid"], progress.c.game_id == row["game_id"])
                .order_by(trophies.c.trophy_id)
            )
            .mappings()
            .all()
        )
        trophy_rows = [
            {
                "id": trophy["trophy_id"],
                "groupId": trophy["group_id"],
                "name": trophy["name"],
                "description": trophy["description"],
                "imageUrl": trophy["image_url"],
                "type": trophy["type"],
                "hidden": trophy["hidden"],
                "earned": trophy["earned"],
                "earnedAt": trophy["earned_at"],
                "earnedRate": trophy["earned_rate"],
            }
            for trophy in rows
        ]
        group_rows = (
            connection.execute(
                sa.select(groups)
                .join(
                    links,
                    (groups.c.service == links.c.service)
                    & (groups.c.set_id == links.c.set_id)
                    & (groups.c.group_id == links.c.group_id),
                )
                .where(links.c.uid == row["uid"], links.c.game_id == row["game_id"])
                .order_by((groups.c.group_id == "default").desc(), groups.c.group_id)
            )
            .mappings()
            .all()
        )
        payload = {
            **row["payload"],
            "trophies": trophy_rows,
            "groups": [{"id": group["group_id"], "name": group["name"]} for group in group_rows],
        }
        connection.execute(
            details.update()
            .where(details.c.uid == row["uid"], details.c.game_id == row["game_id"])
            .values(payload=payload)
        )
